import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Handl SDK Generator","description":"","frontmatter":{"title":"Handl SDK Generator","type":"adr","date":"2026-09-13T00:00:00.000Z","status":"accepted","status_note":"Accepted — port-adapter SDK generation; every FFI arrow carries the `FFI` grade."},"headers":[],"relativePath":"handl/project/adrs/0107-handl-sdk-generator.md","filePath":"vendored/handl/project/adrs/0107-handl-sdk-generator.md"}'),a={name:`handl/project/adrs/0107-handl-sdk-generator.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0107-handl-sdk-generator" tabindex="-1">ADR-0107: Handl SDK Generator <a class="header-anchor" href="#adr-0107-handl-sdk-generator" aria-label="Permalink to “ADR-0107: Handl SDK Generator”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Port-adapter model</strong>: a generated <em>port</em> is the abstract Handl interface; an <em>adapter</em> is the target-specific implementation.</li><li><strong>New crates</strong>: <code>plugin-sdkgen</code> (shared IR), a backend per source format, an emitter per target, and <code>plugin-ext-sdkgen</code> for the CLI.</li><li><strong>Multi-backend by three dimensions</strong> — source format, target ABI, emitter — each pluggable without touching the others.</li><li><strong>The C backend uses <code>libclang</code></strong>, not a hand-rolled parser.</li><li><strong>File output mirrors the module tree</strong>; generated packages are ordinary repos with <code>pkg.hnl</code>/<code>src/</code>.</li><li><strong>Output form</strong>: abstract <code>export</code> in the port, concrete <code>export … :=</code> in the adapter.</li><li><strong>All FFI arrows carry the <code>FFI</code> grade</strong>, so effects are visible in the type.</li><li><strong>Mappings to Handl types/grades are data</strong>, not backend code.</li><li><strong>Doc comments are emitted</strong> from the source into the port.</li><li><strong>Type/grade composition and the CLI surface</strong> are part of the generator: <code>sdkgen</code> subcommands per source/backend.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>SDK generation had a hand-rolled parser and per-backend bespoke code, so every new library or target meant new parsing and mapping logic. Port/adapter plus data mappings makes a new target a backend, and a new source a parser backend.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>A hand-rolled C parser</strong> — <code>libclang</code> is the source of truth.</li><li><strong>Per-backend bespoke mapping code</strong> — mappings are data.</li><li><strong>Ungraded FFI arrows</strong> — every foreign call is <code>FFI</code>.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>libclang</code> becomes a build dependency of the C backend.</li><li>Generated ports/adapters are reviewable Handl, not opaque bindings.</li><li>Doc comments survive generation; the CLI drives source/backend selection.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>sdkgen-c/</code>, <code>sdkgen-webidl/</code>, <code>sdkgen-file/</code>, <code>sdkgen-cli/</code>.</li><li><code>handl-packages/generated/</code> — ports and adapters.</li><li>Generator tests per backend.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The IR, three extensibility dimensions, output layout, mappings and CLI: +<a href="./../design/0107-handl-sdk-generator.html"><code>design/0107-handl-sdk-generator.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};